const EmbedMapAnimation: React.FC<EmbedMapAnimationProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 15,
  accentColor = "#4F46E5",
  trackerTitle = "ENG-402: Strategy Architecture",
  chatChannel = "engineering-team",
  docTitle = "Project Kickoff",
  decisionMapImage = "",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = Math.floor(durationInSeconds * fps);
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Window Proportions
  const wWidth = width * 0.52;
  const wHeight = height * 0.6;
  
  // Staggered Cascade Positions
  const w1X = width * 0.08;
  const w1Y = height * 0.08;
  const w2X = width * 0.24;
  const w2Y = height * 0.2;
  const w3X = width * 0.4;
  const w3Y = height * 0.32;

  // Timing Fractions (Strictly Monotonic)
  const kStart = 0;
  const kW1Open = 0;
  const kW1Embed = totalFrames * 0.1;
  const kW2Open = totalFrames * 0.33;
  const kW2Embed = totalFrames * 0.43;
  const kW3Open = totalFrames * 0.66;
  const kW3Embed = totalFrames * 0.76;

  // Animations - Scales
  const w1Scale = spring({ fps, frame: frame - kW1Open, config: { damping: 14 } });
  const w2Scale = spring({ fps, frame: frame - kW2Open, config: { damping: 14 } });
  const w3Scale = spring({ fps, frame: frame - kW3Open, config: { damping: 14 } });

  const w1EmbedScale = spring({ fps, frame: frame - kW1Embed, config: { damping: 16 } });
  const w2EmbedY = spring({ fps, frame: frame - kW2Embed, config: { damping: 16 } });
  const w3EmbedFade = interpolate(frame, [kW3Embed, kW3Embed + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Cursor Keyframes
  const cursorKeyframes = [
    0,
    totalFrames * 0.05,
    totalFrames * 0.1,  // w1 click
    totalFrames * 0.2,
    totalFrames * 0.38,
    totalFrames * 0.43, // w2 click
    totalFrames * 0.53,
    totalFrames * 0.71,
    totalFrames * 0.76, // w3 click
    totalFrames,
  ];

  const cursorTargetX = [
    width + 100,
    w1X + wWidth * 0.5,
    w1X + wWidth * 0.5,
    w1X + wWidth * 0.5,
    w2X + wWidth * 0.6,
    w2X + wWidth * 0.6,
    w2X + wWidth * 0.6,
    w3X + wWidth * 0.5,
    w3X + wWidth * 0.5,
    width + 100,
  ];

  const cursorTargetY = [
    height + 100,
    w1Y + wHeight * 0.6,
    w1Y + wHeight * 0.6,
    w1Y + wHeight * 0.6,
    w2Y + wHeight * 0.88,
    w2Y + wHeight * 0.88,
    w2Y + wHeight * 0.88,
    w3Y + wHeight * 0.55,
    w3Y + wHeight * 0.55,
    height + 100,
  ];

  const cX = interpolate(frame, cursorKeyframes, cursorTargetX, {
    easing: Easing.inOut(Easing.cubic),
    extrapolateRight: "clamp",
  });

  const cY = interpolate(frame, cursorKeyframes, cursorTargetY, {
    easing: Easing.inOut(Easing.cubic),
    extrapolateRight: "clamp",
  });

  const getClickScale = (f: number, trigger: number) => {
    const diff = f - trigger;
    if (diff >= 0 && diff < 8) {
      return interpolate(diff, [0, 4, 8], [1, 0.85, 1], { extrapolateRight: "clamp" });
    }
    return 1;
  };

  const cursorClickScale =
    getClickScale(frame, kW1Embed) *
    getClickScale(frame, kW2Embed) *
    getClickScale(frame, kW3Embed);

  // Reusable Map Component
  const RenderMap = () => (
    decisionMapImage ? (
      <Img src={decisionMapImage} style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "8px" }} />
    ) : (
      <MapGraphic accentColor={accentColor} />
    )
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: "#FFF",
      }}
    >
      {/* Background Grid for Tech Feel */}
      {!transparentBackground && (
        <svg style={{ position: "absolute", width: "100%", height: "100%", opacity: 0.1 }}>
          <defs>
            <pattern id="dotGrid" width="40" height="40" patternUnits="userSpaceOnUse">
              <circle cx="2" cy="2" r="1.5" fill="#FFFFFF" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#dotGrid)" />
        </svg>
      )}

      {/* Window 1: Issue Tracker */}
      <WindowFrame
        title="Issue Tracker"
        x={w1X}
        y={w1Y}
        width={wWidth}
        height={wHeight}
        scale={w1Scale}
        zIndex={10}
      >
        <div style={{ padding: "40px", display: "flex", flexDirection: "column", gap: "20px", height: "100%" }}>
          <h1 style={{ margin: 0, fontSize: "32px", fontWeight: 700 }}>{trackerTitle}</h1>
          <div
            style={{
              width: "120px",
              height: "28px",
              borderRadius: "14px",
              backgroundColor: `${accentColor}33`,
              color: accentColor,
              fontSize: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontWeight: 600,
              letterSpacing: "0.5px",
            }}
          >
            IN PROGRESS
          </div>
          <div style={{ width: "85%", height: "14px", backgroundColor: "#333", borderRadius: "7px" }} />
          <div style={{ width: "65%", height: "14px", backgroundColor: "#333", borderRadius: "7px" }} />
          <div style={{ flex: 1, position: "relative", marginTop: "16px" }}>
            {frame >= kW1Embed && (
              <div
                style={{
                  width: "100%",
                  height: "280px",
                  transform: `scale(${w1EmbedScale})`,
                  transformOrigin: "top left",
                  willChange: "transform",
                }}
              >
                <RenderMap />
              </div>
            )}
          </div>
        </div>
      </WindowFrame>

      {/* Window 2: Chat Platform */}
      <WindowFrame
        title="Team Chat"
        x={w2X}
        y={w2Y}
        width={wWidth}
        height={wHeight}
        scale={w2Scale}
        zIndex={20}
      >
        <div style={{ display: "flex", height: "100%" }}>
          {/* Sidebar */}
          <div
            style={{
              width: "220px",
              backgroundColor: "#0F0F11",
              borderRight: "1px solid #222",
              padding: "24px 16px",
            }}
          >
            <div style={{ color: "#666", fontWeight: 600, fontSize: "12px", marginBottom: "16px", letterSpacing: "1px" }}>
              CHANNELS
            </div>
            <div
              style={{
                color: "#FFF",
                fontWeight: 500,
                fontSize: "14px",
                padding: "8px 12px",
                backgroundColor: "rgba(255,255,255,0.05)",
                borderRadius: "6px",
              }}
            >
              # {chatChannel}
            </div>
            <div style={{ color: "#888", fontWeight: 500, fontSize: "14px", padding: "8px 12px" }}>
              # general
            </div>
          </div>
          {/* Main Chat Area */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", padding: "24px", position: "relative" }}>
            <div style={{ flex: 1 }} />
            {frame >= kW2Embed && (
              <div
                style={{
                  display: "flex",
                  gap: "16px",
                  marginBottom: "24px",
                  transform: `translateY(${(1 - w2EmbedY) * 30}px)`,
                  opacity: w2EmbedY,
                  willChange: "transform, opacity",
                }}
              >
                <div style={{ width: "44px", height: "44px", borderRadius: "22px", backgroundColor: accentColor }} />
                <div style={{ flex: 1 }}>
                  <div style={{ display: "flex", gap: "12px", alignItems: "baseline", marginBottom: "8px" }}>
                    <span style={{ fontWeight: 600, fontSize: "16px" }}>You</span>
                    <span style={{ fontSize: "12px", color: "#666" }}>Just now</span>
                  </div>
                  <div style={{ width: "420px", height: "240px" }}>
                    <RenderMap />
                  </div>
                </div>
              </div>
            )}
            {/* Input Bar */}
            <div
              style={{
                height: "56px",
                border: "1px solid #333",
                borderRadius: "8px",
                backgroundColor: "#1A1A1A",
                display: "flex",
                alignItems: "center",
                padding: "0 20px",
              }}
            >
              <span style={{ color: "#555", fontSize: "15px" }}>Message #{chatChannel}...</span>
            </div>
          </div>
        </div>
      </WindowFrame>

      {/* Window 3: Documentation */}
      <WindowFrame
        title="Documentation"
        x={w3X}
        y={w3Y}
        width={wWidth}
        height={wHeight}
        scale={w3Scale}
        zIndex={30}
      >
        <div style={{ padding: "60px 80px", display: "flex", flexDirection: "column", gap: "24px", height: "100%", backgroundColor: "#FFFFFF", color: "#111" }}>
          <h1 style={{ margin: 0, fontSize: "44px", fontWeight: 700, letterSpacing: "-0.5px" }}>
            {docTitle}
          </h1>
          <div style={{ width: "40%", height: "12px", backgroundColor: "#E5E5E5", borderRadius: "6px" }} />
          <div style={{ width: "70%", height: "12px", backgroundColor: "#E5E5E5", borderRadius: "6px" }} />
          <div style={{ flex: 1, position: "relative", marginTop: "20px" }}>
            {frame >= kW3Embed && (
              <div
                style={{
                  width: "100%",
                  height: "300px",
                  opacity: w3EmbedFade,
                  transform: `translateY(${(1 - w3EmbedFade) * 15}px)`,
                  willChange: "transform, opacity",
                }}
              >
                <RenderMap />
              </div>
            )}
          </div>
        </div>
      </WindowFrame>

      {/* Animated MacOS Cursor */}
      <svg
        width="40"
        height="40"
        viewBox="0 0 32 32"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        style={{
          position: "absolute",
          left: cX,
          top: cY,
          zIndex: 9999,
          filter: "drop-shadow(0px 8px 12px rgba(0, 0, 0, 0.4))",
          transform: `scale(${cursorClickScale})`,
          transformOrigin: "top left",
          transition: "none",
        }}
      >
        <path
          d="M5.5 28.5L2 2L26 13L15.5 16.5L20.5 25.5L16.5 27.5L11.5 18.5L5.5 28.5Z"
          fill="black"
          stroke="white"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
      </svg>
    </AbsoluteFill>
  );
};

export default EmbedMapAnimation;